  [432235] = { "Rolling Thunderのアビリティを得ます：\n\n$I1\nLightning BoltとChain Lightningには、$N1%の確率で有効なLightning Shieldにチャージを一つ追加する効果があり、最大$N2回のChargesまで増えます。\n\nEarth Shockが、$N3回を超えるLightning Shieldのチャージをすべて解放するようになり、そのダメージを対象に与え、解放したチャージごとに最大マナの$N4%を回復させます。", nil, 0x256c6f01, nil, "um" },
  [432236] = { "手首にRolling Thunderのルーンを刻みます：\n\n$I1\nLightning BoltとChain Lightningは、$N1%の確率で発動中のLightning Shieldにチャージを追加します。最大$N2 Chargesまで蓄積できます。\n\nEarth Shockは、$N3を超えるLightning Shieldのチャージをすべて放出し、そのダメージを対象に与え、放出したチャージごとに最大マナの$N4%を回復するようになります。", nil, 0xe55dbaeb, nil, "um" },
  [432237] = { "Static Shockのアビリティを得ます：\n\n$I1\nLightning Shieldのチャージが$N1回になり、近接攻撃に$N2%の確率（二刀流の間は$N3%の確率）でそのチャージを一つ発動させ、即座に対象にダメージを与える効果が付きます。", nil, 0x4e86219a, nil, "um" },
  [432238] = { "手首にStatic Shockのルーンを刻みます：\n\n$I1\nLightning Shieldのチャージが$N1になり、近接攻撃は$N2%の確率（二刀流中は$N3%の確率）でそのチャージを一つ発動させ、即座に対象にダメージを与えます。", nil, 0x307f3a02, nil, "um" },
